insert into exercises (name, primary_muscle_id, secondary_muscle_fraction, movement_pattern, laterality, stability_demand, equipment_ids, is_weighted, cue_text, difficulty, category, sort_order) values
 ('Chest-to-Bar Pull-Up', 'lats', '{"upper_back": 0.5, "biceps": 0.4}'::jsonb, 'vertical_pull', 'bilateral', 4, '{"pull_up_bar"}', false, 'Pull explosively and drive the elbows down until the chest or upper sternum touches the bar; lower under control.', 3, 'Back', 120),
 ('Explosive High Pull-Up', 'lats', '{"upper_back": 0.5, "biceps": 0.4}'::jsonb, 'vertical_pull', 'bilateral', 4, '{"pull_up_bar"}', false, 'Pull upward with maximum speed, aiming to bring the bar toward the lower chest or waist; lower with control.', 3, 'Back', 121),
 ('False-Grip Pull-Up', 'lats', '{"upper_back": 0.5, "biceps": 0.4, "forearms": 0.3}'::jsonb, 'vertical_pull', 'bilateral', 4, '{"pull_up_bar"}', false, 'Grip with the wrists rolled over the bar so the palms face your chest; pull the chest to the bar keeping the false grip.', 3, 'Back', 122),
 ('Negative Muscle-Up', 'lats', '{"upper_back": 0.5, "triceps": 0.4, "chest": 0.3}'::jsonb, 'vertical_pull', 'bilateral', 4, '{"pull_up_bar"}', false, 'From support above the bar, lower slowly through the transition and down into a dead hang over several seconds; jump or step back up to repeat.', 3, 'Back', 123),
 ('Muscle-Up', 'lats', '{"upper_back": 0.5, "chest": 0.4, "triceps": 0.4}'::jsonb, 'vertical_pull', 'bilateral', 5, '{"pull_up_bar"}', false, 'From a dead hang, pull explosively and roll the wrists over the bar into a straight-arm support; press to lockout, then lower.', 3, 'Back', 124),
 ('Tuck Front Lever', 'lats', '{"upper_back": 0.5, "abs": 0.5}'::jsonb, 'isolation', 'bilateral', 4, '{"pull_up_bar"}', false, 'Hang and lift the body horizontal with the knees tucked tight to the chest; hold the position with a straight back.', 2, 'Back', 125),
 ('Advanced Tuck Front Lever', 'lats', '{"upper_back": 0.5, "abs": 0.5}'::jsonb, 'isolation', 'bilateral', 4, '{"pull_up_bar"}', false, 'Like the tuck front lever, but extend the knees away while keeping the hips tucked; hold a horizontal back.', 3, 'Back', 126),
 ('One-Leg Front Lever', 'lats', '{"upper_back": 0.5, "abs": 0.5}'::jsonb, 'isolation', 'bilateral', 4, '{"pull_up_bar"}', false, 'From a tuck, extend one leg fully and keep the other tucked; hold the body horizontal and switch legs.', 3, 'Back', 127),
 ('Front Lever', 'lats', '{"upper_back": 0.5, "abs": 0.5, "lower_back": 0.3}'::jsonb, 'isolation', 'bilateral', 5, '{"pull_up_bar"}', false, 'Hang and raise the body until it is horizontal with arms straight and legs together; hold with a rigid body.', 3, 'Back', 128),
 ('Dragon Flag', 'abs', '{"lats": 0.3, "lower_back": 0.4}'::jsonb, 'core', 'bilateral', 5, '{"mat","bodyweight"}', false, 'Lie and grip a support behind your head; lift the entire body into a straight line resting on the shoulders; lower slowly.', 3, 'Core', 129),
 ('Skin the Cat', 'lats', '{"abs": 0.4, "front_delts": 0.3}'::jsonb, 'isolation', 'bilateral', 4, '{"pull_up_bar"}', false, 'Hang and tuck the legs through the arms, rotating into a German hang, then return the legs back through under control.', 3, 'Back', 130),
 ('Planche Lean', 'front_delts', '{"chest": 0.4, "triceps": 0.3}'::jsonb, 'horizontal_push', 'bilateral', 4, '{"bodyweight"}', false, 'From a plank, lean the shoulders forward past the hands while keeping a straight body; hold the forward lean.', 3, 'Shoulders', 131),
 ('Pseudo Planche Push-Up', 'front_delts', '{"chest": 0.4, "triceps": 0.4}'::jsonb, 'horizontal_push', 'bilateral', 4, '{"bodyweight"}', false, 'Perform a push-up with the hands near the hips and the shoulders leaning forward; keep the elbows tracking back.', 3, 'Shoulders', 132),
 ('Tuck Planche', 'front_delts', '{"chest": 0.4, "triceps": 0.3}'::jsonb, 'isolation', 'bilateral', 5, '{"bodyweight"}', false, 'With hands on the floor, lean forward and lift the feet, holding the knees tucked to the chest with straight arms.', 3, 'Shoulders', 133),
 ('Advanced Tuck Planche', 'front_delts', '{"chest": 0.4, "triceps": 0.3}'::jsonb, 'isolation', 'bilateral', 5, '{"bodyweight"}', false, 'Like the tuck planche, but extend the knees back while keeping the hips tucked; hold a flat back.', 3, 'Shoulders', 134),
 ('Straddle Planche', 'front_delts', '{"chest": 0.4, "triceps": 0.3}'::jsonb, 'isolation', 'bilateral', 5, '{"bodyweight"}', false, 'Lean forward and lift the legs into a wide straddle while holding the body horizontal on straight arms.', 3, 'Shoulders', 135),
 ('Full Planche', 'front_delts', '{"chest": 0.4, "triceps": 0.3}'::jsonb, 'isolation', 'bilateral', 5, '{"bodyweight"}', false, 'Lean forward and lift the legs together until the body is horizontal and parallel to the floor on straight arms; hold rigid.', 3, 'Shoulders', 136),
 ('Tuck L-Sit', 'abs', '{"triceps": 0.3, "front_delts": 0.3}'::jsonb, 'core', 'bilateral', 4, '{"bodyweight"}', false, 'Sit and press the hands down, lifting the hips and tucking the knees to the chest; hold the support position.', 2, 'Core', 137),
 ('L-Sit', 'abs', '{"triceps": 0.3, "front_delts": 0.3}'::jsonb, 'core', 'bilateral', 4, '{"bodyweight"}', false, 'Support on the hands and lift the legs straight out until parallel to the floor; hold with a tall chest and pointed toes.', 3, 'Core', 138),
 ('V-Sit', 'abs', '{"triceps": 0.3, "front_delts": 0.3}'::jsonb, 'core', 'bilateral', 5, '{"bodyweight"}', false, 'From the L-sit, lift the legs higher toward a V shape; hold the hips in front of the hands.', 3, 'Core', 139),
 ('Pike Compression Hold', 'abs', '{}'::jsonb, 'core', 'bilateral', 3, '{"bodyweight"}', false, 'Seated with legs straight, press the hands beside the hips and lean forward, squeezing the thighs toward the chest; hold.', 2, 'Core', 140);
